// ─── File: LoanStateDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.loan;

import java.math.BigDecimal;
import java.util.logging.*;

public class LoanStateDemo {
    private static final Logger log = Logger.getLogger(LoanStateDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        LoanService service = new LoanService();

        // Composition for variants: HOME loan is a LoanType value, NOT a subclass.
        LoanType home = new LoanType("HOME", new BigDecimal("0.085"), 240);
        Loan rajeshLoan = service.submit("LN-1", "SAV2001", new BigDecimal("3000000"), home);

        log.info("=== Valid lifecycle (entity owns transitions) ===");
        service.review(rajeshLoan);
        service.approve(rajeshLoan);
        service.disburse(rajeshLoan);

        log.info("=== Illegal transition is rejected by the entity ===");
        LoanType car = new LoanType("CAR", new BigDecimal("0.095"), 84);
        Loan priyaLoan = service.submit("LN-2", "CUR3001", new BigDecimal("800000"), car);
        try {
            service.disburse(priyaLoan); // APPLIED -> DISBURSED is illegal
        } catch (IllegalStateException ex) {
            log.warning("Blocked illegal transition: " + ex.getMessage());
        }
    }
}

// ─── model/LoanStatus.java ───
enum LoanStatus { APPLIED, UNDER_REVIEW, APPROVED, DISBURSED, CLOSED, REJECTED }

// ─── model/LoanType.java — COMPOSITION over inheritance for variants ───
class LoanType {
    private final String name;
    private final BigDecimal rate;
    private final int maxTenureMonths;
    LoanType(String name, BigDecimal rate, int maxTenureMonths) {
            this.name = name;
            this.rate = rate
            this.maxTenureMonths = maxTenureMonths;
    }
    String getName() { return name; }
    BigDecimal getRate() { return rate; }
}

// ─── model/Loan.java — the ENTITY owns its guarded state transitions ───
class Loan {
    private static final Logger log = Logger.getLogger(Loan.class.getName());
    private final String loanId;
    private final String accountId;
    private final BigDecimal amount;
    private final LoanType type;        // composed variant, not a subclass
    private LoanStatus status = LoanStatus.APPLIED;

    Loan(String loanId, String accountId, BigDecimal amount, LoanType type) {
            this.loanId = loanId;
            this.accountId = accountId
            this.amount = amount
            this.type = type;
    }

    LoanStatus getStatus() { return status; }
    String getLoanId() { return loanId; }

    // Guarded transitions — illegal moves throw, so status can never be bypassed.
    void startReview() {
        require(LoanStatus.APPLIED, "start review");
        status = LoanStatus.UNDER_REVIEW;
        log.info(() -> loanId + " -> UNDER_REVIEW");
    }
    void approve() {
        require(LoanStatus.UNDER_REVIEW, "approve");
        status = LoanStatus.APPROVED;
        log.info(() -> loanId + " -> APPROVED (" + type.getName() + " @ " + type.getRate() + ")");
    }
    void disburse() {
        require(LoanStatus.APPROVED, "disburse");
        status = LoanStatus.DISBURSED;
        log.info(() -> loanId + " -> DISBURSED Rs." + amount);
    }
    void reject() {
        if (status == LoanStatus.DISBURSED || status == LoanStatus.CLOSED)
            throw new IllegalStateException("cannot reject a " + status + " loan");
        status = LoanStatus.REJECTED;
        log.warning(() -> loanId + " -> REJECTED");
    }

    private void require(LoanStatus expected, String action) {
        if (status != expected)
            throw new IllegalStateException("cannot " + action + " from " + status
                    + " (must be " + expected + ")");
    }
}

// ─── service/LoanService.java — THIN orchestrator, no state rules inside ───
class LoanService {
    private static final Logger log = Logger.getLogger(LoanService.class.getName());

    Loan submit(String id, String acct, BigDecimal amount, LoanType type) {
        Loan loan = new Loan(id, acct, amount, type);
        log.info(() -> "Submitted " + id + " for " + acct + " Rs." + amount);
        return loan; // in real code: repo.save(loan)
    }
    // Each method just coordinates — the ENTITY enforces legality.
    void review(Loan loan)  { loan.startReview(); }
    void approve(Loan loan) { loan.approve(); }
    void disburse(Loan loan){ loan.disburse(); }
    void reject(Loan loan)  { loan.reject(); }
}

// ─── util/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
